/**
 * Laster opp fil-buffere til Rayvns /files-endepunkt.
 *
 * Leser filmetadata fra msg.entry.files og henter buffere fra global context
 * via context_key. Filer uten context_key behandles som upload-feil —
 * de mangler buffer fordi nedlasting tidligere feilet, og registreres
 * eksplisitt i stedet for å hoppes over stille.
 *
 * Upload-feil legges til msg.metadata.failed_files. Siden msg.metadata og
 * entry.metadata er samme objekt (satt av Bridge to Rayvn), er dette
 * konsistent uansett hvilken referanse som brukes videre i flyten.
 *
 * Etter fullføring: msg.payload.files = array av Rayvn fil-IDer.
 */
const target  = msg.metadata.target;
const baseUrl = global.get("parat_bridge").base_urls.rayvn;
const utils   = global.get("utils");
const files   = (msg.entry && msg.entry.files) || [];

// Ingen filer å laste opp — tøm payload.files og fortsett
if (files.length === 0) {
    msg.payload.files = [];
    return msg;
}

const resolved = [];
const failed   = [];

for (const file of files) {
    // Manglende context_key betyr at nedlasting aldri lyktes.
    // Registrer som upload-feil så den inngår i det endelige feilbildet.
    if (!file.context_key) {
        failed.push({ name: file.name || "ukjent fil", reason: utils.FILE_REASONS.UPLOAD_FAILED });
        continue;
    }

    const buffer = global.get("files." + file.context_key);

    if (!buffer || buffer.length === 0) {
        node.warn("Ingen buffer funnet for context_key: " + file.context_key);
        failed.push({ name: file.name || "ukjent fil", reason: utils.FILE_REASONS.UPLOAD_FAILED });
        continue;
    }

    try {
        const boundary = "----PBBoundary" + Date.now();
        const header   = `--${boundary}\r\nContent-Disposition: form-data; name="file"; filename="${file.name || "file.bin"}"\r\nContent-Type: ${file.type || "application/octet-stream"}\r\n\r\n`;
        const footer   = `\r\n--${boundary}--\r\n`;
        const body     = Buffer.concat([Buffer.from(header), buffer, Buffer.from(footer)]);

        const res = await nodeFetch(baseUrl + "/files", {
            method:  "POST",
            headers: {
                "Authorization": "Bearer " + target.api_key,
                "Content-Type":  "multipart/form-data; boundary=" + boundary
            },
            body
        });

        if (res.ok) {
            const data = await res.json();
            resolved.push(data.id);
            node.log(`Fil lastet opp: ${file.name} → ${data.id}`);
        } else {
            node.warn(`Rayvn /files returnerte ${res.status} for ${file.name}`);
            failed.push({ name: file.name || "ukjent fil", reason: utils.FILE_REASONS.UPLOAD_FAILED });
        }
    } catch (e) {
        node.warn(`Feil ved opplasting av ${file.name}: ${e.message}`);
        failed.push({ name: file.name || "ukjent fil", reason: utils.FILE_REASONS.UPLOAD_FAILED });
    }
}

// Erstatt entry-filene med Rayvn fil-IDer klare for POST
msg.payload.files = resolved;

// Legg upload-feil til metadata.failed_files (= entry.metadata.failed_files)
if (failed.length > 0) {
    msg.metadata.failed_files = [
        ...(msg.metadata.failed_files || []),
        ...failed
    ];
}

return msg;

/**
 * Patcher msg.payload.text med mottakernotis basert på komplett feilbilde.
 *
 * Kjøres etter alle upload-forsøk — metadata.failed_files inneholder nå
 * classify-feil, nedlastingsfeil og upload-feil samlet.
 *
 * msg.payload.files inneholder Rayvn fil-IDer etter vellykket upload,
 * og brukes til å beregne korrekt antall vellykkede overføringer.
 *
 * Ingen feil → msg passerer uendret.
 */
const failed = msg.metadata.failed_files || [];

if (failed.length === 0) return msg;

const succeeded = msg.payload.files.length;
const total     = succeeded + failed.length;
const notice    = " [" + failed.length + "/" + total
                + " vedlegg ikke overført. Avsender mottar instruks om alternativ håndtering]";

msg.payload.text = (msg.payload.text || "") + notice;

return msg;

const target = msg.metadata.target;

if (!target || !target.api_key || !target.client_specific.log_id) {
    node.error("Rayvn ikke konfigurert på denne tilkoblingen");
    return null;
}

msg.url = global.get("parat_bridge").base_urls.rayvn
    + "/logs/" + target.client_specific.log_id + "/entry";

msg.headers = {
    "Authorization": "Bearer " + target.api_key,
    "Content-Type":  "application/json",
    "Accept":        "application/json"
};

return msg;

msg.topic = "response";

if (msg.statusCode === 200) {
    msg.result = true;
} else {
    msg.result = false;
}

return msg;

/**
 * Brenner avsendernotifikasjon om vedleggsfeil etter vellykket POST.
 *
 * Leser metadata.failed_files — komplett bilde inkl. upload-feil.
 * Sender kun notifikasjon om POST lyktes; ved POST-feil håndterer
 * køsystemet retry og varsling.
 *
 * Output 1
 * output 2: notifikasjonspayload til attachment notification-handleren
 */
if (msg.result !== true) return [msg, null];

const failed = msg.metadata.failed_files || [];
if (failed.length === 0) return [msg, null];

const notification = {
    payload: {
        entry_id:     msg.entry.id,
        failed_files: failed,
        entry_author: msg.entry.author,
        metadata:     msg.metadata
    }
};

return [msg, notification];
